import{_ as e,o as d,c as a,a6 as r}from"./chunks/framework.B_q3ZJNF.js";const m=JSON.parse('{"title":"信号与进程控制速查","description":"","frontmatter":{},"headers":[],"relativePath":"nginx-internals-course/signals-reference.md","filePath":"nginx-internals-course/docs/signals-reference.md"}'),s={name:"nginx-internals-course/signals-reference.md"};function n(o,t,i,l,c,p){return d(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="信号与进程控制速查" tabindex="-1">信号与进程控制速查 <a class="header-anchor" href="#信号与进程控制速查" aria-label="Permalink to &quot;信号与进程控制速查&quot;">​</a></h1><p>第 7 章的信号表扩充成运维向速查：谁发、谁收、干什么、常用命令。压测和发版前翻这一页就够。</p><h2 id="常用信号" tabindex="-1">常用信号 <a class="header-anchor" href="#常用信号" aria-label="Permalink to &quot;常用信号&quot;">​</a></h2><table tabindex="0"><thead><tr><th>信号</th><th>语义</th><th>收信方</th><th>常用命令</th></tr></thead><tbody><tr><td>TERM</td><td>立即退出（快关）</td><td>worker / master</td><td><code>nginx -s stop</code></td></tr><tr><td>QUIT</td><td>优雅退出：不再接新客，存量连接送完再走</td><td>worker / master</td><td><code>nginx -s quit</code></td></tr><tr><td>HUP</td><td>重新读配置并平滑换血（reload）</td><td>master</td><td><code>nginx -s reload</code></td></tr><tr><td>USR1</td><td>重新打开日志文件（日志切割后换新文件写）</td><td>master</td><td><code>nginx -s reopen</code></td></tr><tr><td>USR2</td><td>热升级：用新二进制启动新 master，继承监听端口</td><td>master</td><td><code>kill -USR2 &lt;master-pid&gt;</code></td></tr><tr><td>WINCH</td><td>让旧 master 的 worker 优雅退休（配合 USR2 热升级）</td><td>master</td><td><code>kill -WINCH &lt;旧master-pid&gt;</code></td></tr><tr><td>CHLD</td><td>子进程退出通知（内核自动发，master 借此收尸并补招 worker）</td><td>master</td><td>——（不用手动发）</td></tr><tr><td>KILL</td><td>无条件击杀，进程没有机会清理（最后手段）</td><td>任意</td><td><code>kill -9 &lt;pid&gt;</code></td></tr></tbody></table><h2 id="三种关机姿势的区别" tabindex="-1">三种关机姿势的区别 <a class="header-anchor" href="#三种关机姿势的区别" aria-label="Permalink to &quot;三种关机姿势的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>用法</th><th>存量连接</th><th>TIME_WAIT 侧</th></tr></thead><tbody><tr><td>快关</td><td><code>-s stop</code>（TERM）</td><td>立刻断开</td><td>客户端侧产生</td></tr><tr><td>优雅关</td><td><code>-s quit</code>（QUIT）</td><td>送完最后一个才退</td><td>服务端侧产生</td></tr><tr><td>热升级</td><td>USR2 + WINCH + TERM</td><td>全程不断</td><td>无</td></tr></tbody></table><h2 id="reload-时序-第-7-章六步的速查版" tabindex="-1">reload 时序（第 7 章六步的速查版） <a class="header-anchor" href="#reload-时序-第-7-章六步的速查版" aria-label="Permalink to &quot;reload 时序（第 7 章六步的速查版）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. master 收 HUP</span></span>
<span class="line"><span>2. 重读 nginx.conf —— 解析失败则原样放弃，线上无感</span></span>
<span class="line"><span>3. 用新配置 fork 新 worker</span></span>
<span class="line"><span>4. 向旧 worker 发 QUIT</span></span>
<span class="line"><span>5. 旧 worker 不再接新客，存量连接服务到底</span></span>
<span class="line"><span>6. 旧 worker 逐一送客退出；期间两代 worker 并存是正常账单</span></span></code></pre></div><h2 id="查看与定位" tabindex="-1">查看与定位 <a class="header-anchor" href="#查看与定位" aria-label="Permalink to &quot;查看与定位&quot;">​</a></h2><ul><li><code>ps -ef | grep nginx</code>：找 master/worker（master 的父进程是 1 号或启动者；root 那个是 master）。</li><li><code>nginx -t</code>：只验配置不生效——reload 前先跑它，就是六步时序里第 2 步的保命符。</li><li><code>cat /var/run/nginx.pid</code>：master 的 PID，热升级三连发都对着它。</li></ul>`,10)])])}const u=e(s,[["render",n]]);export{m as __pageData,u as default};
